import numpy as np, itertools
lines = open('initial.xyz').read().split('\n')[2:]
ats = []
for i,l in enumerate(lines):
    p = l.split()
    if len(p)==4:
        ats.append((i,p[0], np.array(list(map(float,p[1:])))))
for (i1,s1,p1),(i2,s2,p2) in itertools.combinations(ats,2):
    d = np.linalg.norm(p1-p2)
    if d < 1.0:
        print(i1,s1,p1, i2,s2,p2, round(d,3))
